const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(n,d=1)=>Number.isFinite(n)?n.toFixed(d):'N/A';
export function openLimitBreak(host,{exit,notify,ask,initialPage='setup'}={}){
 let disposed=false,token=0,page='setup',runtime,view,graphics,monitor,controls,tap,input,model,follow,synth,wind,run=null,tuning=null,lastResult=null,paused=false,committed=false,mode='adventure',players=1,ids=[DB.active,DB.profiles.find(p=>p.id!==DB.active)?.id],preset=DB.settings.limitBreak?.preset||'auto',target=30,lastHUD=0,cameraMode=false;
 const hub=new GamepadHub({players:2,onConnect:(i)=>notify('Controller ready for Player '+(i+1)),onDisconnect:i=>{if(page==='play'&&view&&mode==='adventure'){pause(true,'Controller disconnected');notify('Player '+(i+1)+' controller disconnected. Reconnect or use touch, then resume.');}}});
 const history=()=>DB.settings.limitBreak?.history||[],$=s=>host.querySelector(s);
 const gate=createInstructionGate({game:'limit',onBack:exit,onReview:()=>{if(!view)return false;const was=paused;pause(true,'Instructions opened');return()=>pause(was);}});
 function disposeScene(){token++;controls?.dispose();tap?.dispose();synth?.dispose();wind?.dispose();monitor?.dispose();view?.dispose();graphics?.dispose();runtime?.dispose();runtime=view=graphics=monitor=controls=tap=synth=wind=null;run=null;}
 function storePreferences(){DB.settings.limitBreak={...(DB.settings.limitBreak||{}),preset,history:history().slice(-20)};save();}
 function pause(value,reason='Paused'){paused=!!value||mode!=='adventure'&&!run;input?.clear();if(value&&run&&!run.done){run.abort(reason);run=null;tuning=null;if($('#lbBenchStatus'))$('#lbBenchStatus').textContent='Benchmark stopped: '+reason+'. No result was saved.';}runtime?.pause(paused);synth?.pause(paused);wind?.pause(paused);if($('#lbPause'))$('#lbPause').textContent=paused?'RESUME':'PAUSE';if($('#lbPauseCard'))$('#lbPauseCard').hidden=!paused;}
 async function leave(){if(page==='play'&&model&&!model.done&&!await ask('Leave the forest?','Completed runs and benchmark history are saved. This unfinished adventure will restart.'))return;disposeScene();exit();}
 function options(id){return DB.profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('');}
 function presets(){return `<option value="auto" ${preset==='auto'?'selected':''}>Auto Detect</option>`+Object.entries(GRAPHICS_PRESETS).map(([k,v])=>`<option value="${k}" ${preset===k?'selected':''}>${v.label}</option>`).join('');}
 function setup(){disposeScene();page='setup';paused=false;host.innerHTML=`<section class="lb-app"><header class="lb-header"><button id="lbExit">← ARCADE</button><b>PROJECT <em>LIMIT BREAK</em></b><span>MILESTONE 02 · THE LIVING FOREST</span></header><div class="lb-setup"><article class="lb-intro"><div class="lb-cover">${limitCover()}</div><p class="lb-eyebrow">A NEW WORLD. AN HONEST BENCHMARK.</p><h1>The forest<br><em>remembers.</em></h1><p>Follow the old woodland trail. Restore three lanterns, face the forest sentinels and open the Wayfarer Gate, alone or with a friend.</p><div class="lb-tags"><span>IMPORTED, ANIMATED HEROES</span><span>TEXTURED 3D FOREST</span><span>LOCAL PHYSICS</span></div></article><section class="lb-config"><p class="lb-eyebrow">CHOOSE YOUR EXPEDITION</p><div class="lb-mode"><button data-mode="adventure" class="${mode==='adventure'?'selected':''}">PLAY THE FOREST<small>Explore · fight · restore</small></button><button data-mode="baseline" class="${mode==='baseline'?'selected':''}">FOREST BASELINE<small>Automatic · measured frames</small></button></div>${mode==='adventure'?`<div class="lb-mode"><button data-players="1" class="${players===1?'selected':''}">ONE EXPLORER</button><button data-players="2" class="${players===2?'selected':''}" ${DB.profiles.length<2?'disabled':''}>TOGETHER · 2 PLAYERS</button></div>`:''}<div class="lb-fields"><label>${mode==='adventure'?'Player 1':'Explorer profile'}<select id="lbP1">${options(ids[0])}</select></label>${players===2&&mode==='adventure'?`<label>Player 2<select id="lbP2">${options(ids[1])}</select></label>`:''}<label>Graphics<select id="lbPreset">${presets()}</select></label></div><p class="lb-note">${mode==='baseline'?'35 seconds: warm-up, then five fixed forest stages. Input is disabled during the recorded camera path. No quality reductions or arcade points.':'WASD / arrows, touch sticks or gamepads. Tap the ground to walk. F / R / C strikes, casts a pulse and dodges; Player 2 uses Numpad 2 / 3 / 4. Touch players have their own action buttons. Co-op shares the objective.'}</p><button id="lbPlay" class="lb-primary">${mode==='baseline'?'RUN FOREST BASELINE':'ENTER THE LIVING FOREST'} ↗</button><button id="lbHistory" class="lb-secondary">BENCHMARK HISTORY · ${history().length} RUNS</button><button id="lbControllerHelp" class="lb-secondary">XBOX CONTROLLER SETUP & CONTROLS</button><p class="lb-pad-status" id="lbPadStatus"></p><div class="lb-roadmap"><b>THE FIRST COMPLETE CHAPTER</b><p>This release delivers the Living Forest and its baseline. Milestone 2 adds real encounters, ranged pulses, dodges, moving-prop collisions and a working gate. Castle interiors and the Chaos Chamber remain later milestones.</p><p>GPU effects are capability-dependent. The built-in monitor labels the active renderer and unavailable readings.</p></div></section></div><div id="lbDialog" class="lb-dialog" hidden></div></section>`;
  $('#lbExit').onclick=leave;host.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;setup();});host.querySelectorAll('[data-players]').forEach(b=>b.onclick=()=>{players=+b.dataset.players;setup();});$('#lbPreset').onchange=e=>preset=e.target.value;$('#lbP1').onchange=e=>ids[0]=e.target.value;if($('#lbP2'))$('#lbP2').onchange=e=>ids[1]=e.target.value;$('#lbHistory').onclick=showHistory;$('#lbControllerHelp').onclick=showControllerGuide;$('#lbPlay').onclick=()=>{if(players===2&&mode==='adventure'&&ids[0]===ids[1])return notify('Choose different profiles for co-op.');DB.active=ids[0];storePreferences();gate.show({players:(players===2&&mode==='adventure'?ids:ids.slice(0,1)).map(id=>player(id)?.name),mode,modeLabel:mode==='baseline'?'Forest Baseline · automatic':players===2?'Cooperative expedition':'Solo expedition',coop:players===2,difficulty:mode==='baseline'?'Measured forest traversal':'Forest Adventure'},()=>launch(mode));};}
 function playerControls(){return Array.from({length:mode==='adventure'?players:1},(_,i)=>`<div class="lb-pad" data-owner="${i}"><div class="lb-stick" data-stick="${i}" aria-label="Player ${i+1} movement joystick"><i></i></div><div class="lb-pad-actions"><button data-select="${i}">P${i+1} · ${esc(player(ids[i])?.name)}</button><div class="lb-health" id="lbHealth${i}"></div><div><button data-action="jump" data-player="${i}">JUMP</button><button data-action="interact" data-player="${i}">INTERACT</button><button data-run="${i}" aria-pressed="false">RUN</button><button data-action="attack" data-player="${i}">STRIKE</button><button data-action="cast" data-player="${i}">PULSE</button><button data-action="dodge" data-player="${i}">DODGE</button></div></div></div>`).join('');}
 async function launch(requested=mode){disposeScene();page='play';mode=requested;paused=false;committed=false;lastHUD=0;const ticket=token;host.innerHTML=`<section class="lb-app lb-playing"><header class="lb-header"><button id="lbExit">← ARCADE</button><b>THE LIVING FOREST</b><nav><button id="lbMonitorToggle">MONITOR</button><button id="lbSettings" disabled>SETTINGS</button><button id="lbHelp" disabled>HOW TO PLAY</button><button id="lbPause" disabled>PAUSE</button><button id="lbFull" aria-label="Fullscreen">⛶</button></nav></header><div class="lb-stage"><canvas id="lbCanvas" tabindex="0" aria-label="Project Limit Break third-person Living Forest"></canvas><div class="lb-objective"><span id="lbRenderer">LOADING LOCAL 3D ASSETS</span><h2 id="lbObjective">The forest is waking…</h2><p id="lbHint">Loading imported models, textures and the local Havok world.</p><p id="lbStatus" role="status"></p><small id="lbPadStatus" class="lb-pad-status"></small></div><div class="lb-map"><canvas id="lbMap" width="180" height="190" aria-label="Forest map and lantern locations"></canvas><span>WAYFARER’S MAP</span></div><aside id="lbMonitor" class="lb-monitor" hidden></aside><div class="lb-bench-status" id="lbBenchStatus" hidden></div><div class="lb-touch" id="lbTouch">${playerControls()}</div><button class="lb-camera" id="lbCamera">CAMERA · RIGHT-DRAG / ORBIT</button><div id="lbPauseCard" class="lb-pause-card" hidden><h2>A moment in the woods.</h2><button id="lbResume" class="lb-primary">BACK TO THE FOREST</button><button id="lbRestart">RESTART CHAPTER</button><button id="lbSafe">RESET TO SAFE GRAPHICS</button><button id="lbPadGuide">XBOX CONTROLS</button></div><div id="lbLoading" class="lb-loading"><b>Unpacking the woodland…</b><p>All models, textures and physics run locally.</p></div></div><div id="lbDialog" class="lb-dialog" hidden></div></section>`;
  $('#lbExit').onclick=leave;$('#lbPadGuide').onclick=showControllerGuide;$('#lbPause').onclick=()=>pause(!paused);$('#lbResume').onclick=()=>mode==='adventure'?pause(false):launch('adventure');$('#lbRestart').onclick=()=>launch('adventure');$('#lbSafe').onclick=()=>{preset='low';if(mode!=='adventure')launch('adventure');else{applySettings();pause(false);}};$('#lbHelp').onclick=()=>gate.review();$('#lbFull').onclick=()=>document.getElementById('fullscreen')?.click();$('#lbSettings').onclick=()=>{pause(true,'Settings opened');showSettings();};$('#lbMonitorToggle').onclick=()=>$('#lbMonitor').hidden=!$('#lbMonitor').hidden;$('#lbCamera').onclick=()=>{cameraMode=!cameraMode;$('#lbCamera').textContent=cameraMode?'CAMERA · DRAG TO ORBIT':'TAP GROUND TO WALK';};
  try{if(mode==='adventure'){wind=createForestAmbience({contextFactory:audio,getSettings:()=>({muted:DB.settings.muted,volume:DB.settings.sound/100})});wind.start();}model=new LivingForest({players:mode==='adventure'?players:1,encounters:mode==='adventure'});const manifest=await fetch('assets/limit/manifest.json').then(r=>{if(!r.ok)throw Error('Forest asset manifest unavailable');return r.json();});if(disposed||ticket!==token)return;const r=await create3DScene($('#lbCanvas'),{quality:'low',camera:{alpha:-Math.PI/2,beta:1.23,radius:6.5,minRadius:4,maxRadius:16,minBeta:.4,maxBeta:1.3,target:[0,1,-16]},lighting:{ambient:.55,sun:1.2},onError:e=>fatal(e)});if(disposed||ticket!==token){r.dispose();return;}runtime=r;graphics=createGraphicsControl(r);graphics.apply(preset);monitor=createSceneMonitor(r);const v=await createLivingForestScene(r,model,graphics,{manifest,onCue:cue});if(disposed||ticket!==token){v.dispose();r.dispose();return;}view=v;follow=createThirdPersonCamera(r,{distance:6.4,maxDistance:14,groundAt:forestHeight,obstacles:model.layout.obstacles.map(o=>({minX:o.x-o.w/2,maxX:o.x+o.w/2,minY:o.minY,maxY:o.maxY,minZ:o.z-o.d/2,maxZ:o.z+o.d/2}))});input=new ActionInput(model.players.length,{gamepad:XBOX_ACTIONS});controls=bindActionInput(host,input,{onPause:()=>pause(!paused),pauseEnabled:()=>page==='play'&&!gate.pending&&$('#lbDialog').hidden,onSelect:i=>notify('Mouse controls: '+player(ids[i]).name),enabled:()=>!paused&&!gate.pending&&mode==='adventure'&&!run&&$('#lbDialog').hidden});tap=bind3DInput($('#lbCanvas'),r,{cameraMode:()=>cameraMode||mode!=='adventure',down:p=>{if(!paused&&mode==='adventure')model.navigate(input.selected,p);}});host.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{input.selected=+b.dataset.select;notify('Tap-to-walk controls '+player(ids[input.selected]).name);});
   synth=createSynthAudio({contextFactory:audio,ownsContext:false,getSettings:()=>({muted:DB.settings.muted,volume:DB.settings.sound/100*.1})});$('#lbLoading').hidden=true;for(const id of ['lbSettings','lbHelp','lbPause'])$('#'+id).disabled=false;$('#lbRenderer').textContent=graphics.caps.renderer+' · '+graphics.settings.label+' · MILESTONE 2';r.setUpdate(frame);view.update(0);follow.update(model.players,0);r.pause(false);if(mode==='baseline')startBenchmark();if(mode==='tune')startTuning();
  }catch(e){if(ticket===token)fatal(e);}
 }
 function cue(e){if(e.type==='water')notify('Deep water — returned to your last lantern. Cross at the bridge.');if(e.type==='lantern')notify(LANTERNS[e.id].name+' restored');if(['lantern','finish'].includes(e.type))for(const[f,i]of [[523,0],[659,1],[784,2]])synth?.play({frequency:f,duration:.26,delay:i*.1,volume:.55});if(e.type==='talk')notify(model.message);if(e.type==='notice')notify('A sentinel spotted you — watch its wind-up.');if(e.type==='door')notify('Gate opening — both explorers can pass.');if(['attack','pulse','hit','dodge','defeat'].includes(e.type))synth?.play({frequency:{attack:160,pulse:650,hit:95,dodge:300,defeat:480}[e.type],duration:.1,type:e.type==='hit'?'triangle':'sine',slide:e.type==='pulse'?-.3:.3,volume:.22});if(e.type==='jump')synth?.play({frequency:180,duration:.08,type:'sine',volume:.15});}
 function fatal(error){if($('#lbLoading')){$('#lbLoading').hidden=false;$('#lbLoading').innerHTML=`<h2>The forest could not open.</h2><p>${esc(error.message)}</p><button id="lbRetry">RETRY WITH LOW GRAPHICS</button><button id="lbBack">BACK TO SETUP</button>`;$('#lbRetry').onclick=()=>{preset='low';launch('adventure');};$('#lbBack').onclick=setup;}runtime?.pause(true);}
 function frame(dt,info={}){if(!view||disposed)return;if(dt>0){monitor.frame(info.frameMs);if(run){run.frame(info.frameMs);const total=run.stages.reduce((n,s)=>n+s.seconds,0),stage=run.stage,start=run.stages.slice(0,stage).reduce((n,s)=>n+s.seconds,0),progress=Math.max(0,Math.min(1,(run.recorded-start)/run.stages[stage].seconds));if(run.elapsed<run.warmup){const sweep=run.elapsed/run.warmup*run.stages.length;view.benchmarkCamera(Math.min(run.stages.length-1,Math.floor(sweep)),sweep%1);}else view.benchmarkCamera(stage,progress);$('#lbBenchStatus').textContent=run.elapsed<run.warmup?`WARM-UP · ${Math.ceil(run.warmup-run.elapsed)}s`:`${tuning?'SETTINGS TEST':'FOREST BASELINE'} · ${run.stages[stage].name} · ${Math.min(100,run.recorded/total*100).toFixed(0)}%`;view.syncCollision?.();model.update(dt,[]);view.update(dt,{benchmark:run});if(run.done)finishBenchmark();}else{const pads=model.players.map((_,i)=>hub.pad(i)),intents=model.players.map((p,i)=>{const a=input.read(i,pads[i]);return{...a,...cameraRelativeMovement(a,runtime.camera.alpha)};});view.syncCollision?.();model.update(dt,intents);follow.update(model.players,dt);view.update(dt);if(model.done&&!committed)complete();}}
  if((info.wallTime||performance.now())-lastHUD>250){lastHUD=info.wallTime||performance.now();hud();}
 }
 function hud(){if(!runtime)return;$('#lbPadStatus').textContent=hub.slots.filter(Boolean).length?hub.slots.map((s,i)=>s?'P'+(i+1)+' controller ready':null).filter(Boolean).join(' · ')+' · X strike · B dodge · Y use · RT pulse':'Xbox: pair in Windows, then press a controller button.';wind?.update();const near=model.nearest(model.players[input?.selected||0]);$('#lbObjective').textContent=run?'Forest Baseline · automatic':model.done?'The forest remembers.':`${model.lit.size}/3 LANTERNS · ${model.defeated}/3 SENTINELS`;$('#lbHint').textContent=run?'Fixed settings · seeded scene · measured frames · no arcade points':near?`${near.name} · ${near.d.toFixed(0)} m · ${near.d<2.2?'Press INTERACT':'follow the map'}`:model.message;$('#lbStatus').textContent=run?'':model.message;for(const [i,p]of model.players.entries()){const el=$('#lbHealth'+i);if(el)el.innerHTML=`<b>${p.alive?Math.ceil(p.hp)+' / '+p.maxHP+' HP':'RECOVERING AT CHECKPOINT'}</b><meter min="0" max="${p.maxHP}" value="${p.hp}" aria-label="Player ${i+1} health"></meter><small>Pulse ${Math.max(0,p.castReady-model.clock).toFixed(1)}s · Dodge ${Math.max(0,p.dodgeReady-model.clock).toFixed(1)}s</small>`;}host.querySelectorAll('[data-action]').forEach(b=>{const p=model.players[+b.dataset.player],key=b.dataset.action;b.disabled=!p?.alive||['attack','cast','dodge'].includes(key)&&model.clock<p[key+'Ready'];});const m=monitor.snapshot({characters:view.characters});if(!$('#lbMonitor').hidden)$('#lbMonitor').innerHTML=`<header>ACTUAL FRAME MONITOR</header><b>${fmt(m.currentFPS,0)} <small>FPS NOW</small></b><div class="lb-metrics"><span>Average <strong>${fmt(m.averageFPS)}</strong></span><span>1% low <strong>${fmt(m.onePercentLowFPS)}</strong></span><span>Median <strong>${fmt(m.medianMs)} ms</strong></span><span>p95 <strong>${fmt(m.p95Ms)} ms</strong></span><span>Worst <strong>${fmt(m.worstMs)} ms</strong></span><span>Spikes &gt;50ms <strong>${m.spikes}</strong></span><span>Characters / bodies <strong>${m.characters} / ${m.bodies}</strong></span><span>Meshes / triangles <strong>${m.meshes} / ${Math.round(m.triangles)}</strong></span><span>Draw calls <strong>${fmt(m.drawCalls,0)}</strong></span><span>GPU timer <strong>${fmt(m.gpuMs)} ms</strong></span><span>JS heap only <strong>${fmt(m.jsHeapMiB)} MiB</strong></span><span>System RAM / VRAM <strong>N/A / N/A</strong></span></div><div class="lb-histogram">${m.distribution.map((b,i)=>`<span title="${b.count} frames"><i style="height:${Math.max(2,b.count/Math.max(1,m.frames)*45)}px"></i><small>${['≤8','≤17','≤33','≤50','≤100','>100'][i]}</small></span>`).join('')}</div><p>${graphics.caps.renderer} · ${runtime.canvas.width}×${runtime.canvas.height}</p>`;drawMap();}
 function drawMap(){const c=$('#lbMap').getContext('2d');c.clearRect(0,0,180,190);c.fillStyle='#28443c';c.fillRect(0,0,180,190);const xy=p=>[90+p.x*4,174-(p.z+19)*4];c.strokeStyle='#a4a17a';c.lineWidth=4;c.beginPath();c.moveTo(...xy({x:0,z:-17}));c.lineTo(...xy({x:0,z:18}));c.stroke();c.fillStyle='#407f80';c.fillRect(0,93,180,12);c.fillStyle='#b5ac80';c.fillRect(85,91,10,17);for(const l of LANTERNS){const[x,y]=xy(l);c.fillStyle=model.lit.has(l.id)?'#f3d284':'#94bcb0';c.beginPath();c.arc(x,y,5,0,Math.PI*2);c.fill();c.fillStyle='#fff5d5';c.font='10px system-ui';c.fillText(String(l.id+1),x+7,y+3);}for(const[i,p]of model.players.entries()){const[x,y]=xy(p);c.fillStyle=i?'#e5a47f':'#e7dbac';c.beginPath();c.arc(x,y,4,0,Math.PI*2);c.fill();}for(const u of [...model.npcs,...model.enemies]){if(!u.alive)continue;const[x,y]=xy(u);c.fillStyle=u.team===1?'#df9176':'#81b8aa';c.fillRect(x-2,y-2,5,5);}const[sx,sy]=xy(FOREST_SWITCH);c.fillStyle=model.doorOpened?'#e4d394':'#ae8360';c.fillRect(sx-2,sy-3,5,6);const[x,y]=xy(FOREST_GATE);c.strokeStyle='#e6d6a3';c.strokeRect(x-6,y-5,12,9);}
 function complete(){committed=true;const s=model.summary();for(const id of ids.slice(0,players)){commitRound([{id,score:s.score,hits:3,errors:s.retries+s.defeats,details:{lanterns:s.lanterns,sentinels:s.sentinels,defeats:s.defeats},completed:true,elapsed:s.elapsed,duration:s.elapsed,soloWin:true}],{game:'limit',difficulty:3,learn:false,mode:'solo',ruleset:'limit-forest-v2',levelId:1,competition:players===2?'coop':'solo',challengeKey:'forest-2',seed:model.seed});unlock(player(id),'limit-first');unlock(player(id),'limit-sentinels');if(players===2)unlock(player(id),'limit-team');}save();dialog(`<p class="lb-eyebrow">CHAPTER COMPLETE · ${fmt(s.elapsed)} SECONDS</p><h2>The way is open.</h2><p>Three lanterns restored. Three sentinels defeated.<br>${s.retries} water recoveries · ${s.defeats} combat recoveries.<br>${s.score} points saved for ${ids.slice(0,players).map(id=>esc(player(id).name)).join(' + ')}.</p><button id="lbAgain" class="lb-primary">EXPLORE AGAIN</button><button id="lbBenchFromWin">RUN THE FOREST BASELINE</button><button id="lbReturn">ARCADE</button>`,()=>{$('#lbAgain').onclick=()=>launch('adventure');$('#lbBenchFromWin').onclick=()=>launch('baseline');$('#lbReturn').onclick=leave;});}
 function startBenchmark(stages=FOREST_BENCHMARK_STAGES,warmup=5){run=new BenchmarkRun({stages,warmup,seed:model.seed,settings:graphics.settings,metadata:{...monitor.metadata(),baseline:'living-forest-v2-navigation',scope:'Milestone 2 forest traversal, obstacle-aware wardens and physics; no castle/combat stress/chaos results',characters:view.characters,weather:'day',physicsObjects:view.props.length,audio:'No ambience during baseline',adaptiveQuality:false,warmupPath:'One pre-recording sweep of all forest stages'}});view.setWeather('day');view.resetPhysics();$('#lbTouch').hidden=true;$('#lbBenchStatus').hidden=false;$('#lbPauseCard').hidden=true;paused=false;runtime.pause(false);$('#lbMonitor').hidden=false;}
 function finishBenchmark(){const result=run.result();run=null;if(tuning){tuning.results.push({preset:tuning.queue[tuning.index],report:result.overall});tuning.index++;if(tuning.index<tuning.queue.length){preset=tuning.queue[tuning.index];graphics.apply(preset);view.refresh();startBenchmark([{name:'Forest auto-tune sample',seconds:5}],2);return;}const recommendation=recommendPreset(tuning.results,tuning.target);preset=recommendation.preset;graphics.apply(preset);view.refresh();storePreferences();const text=recommendation.metTarget?`Recommended ${GRAPHICS_PRESETS[preset].label} for ${recommendation.target} FPS.`:`${recommendation.target} FPS was not sustained with the tested frame-pacing thresholds. Low is selected; you can override it.`;tuning=null;pause(true);dialog(`<h2>Your measured settings</h2><p>${esc(text)}</p><button id="lbCloseTune" class="lb-primary">CONTINUE EXPLORING</button>`,()=>$('#lbCloseTune').onclick=()=>launch('adventure'));return;}
  lastResult={...result,id:uid(),at:Date.now()};DB.settings.limitBreak={...(DB.settings.limitBreak||{}),preset,history:[...history(),lastResult].slice(-20)};save();pause(true);showResult(lastResult);
 }
 function startTuning(){tuning={queue:graphics.caps.gpu?['low','medium','high','ultra','maximum']:['low'],index:0,results:[],target};preset='low';graphics.apply(preset);view.refresh();startBenchmark([{name:'Forest auto-tune sample',seconds:5}],2);}
 function applySettings(overrides={}){if(run){run.abort('Graphics changed');run=null;tuning=null;}graphics?.apply(preset,overrides);view?.refresh();follow?.reset();storePreferences();if($('#lbRenderer'))$('#lbRenderer').textContent=graphics.caps.renderer+' · '+graphics.settings.label+' · MILESTONE 2';}
 function dialog(html,bind){const d=$('#lbDialog');d.hidden=false;d.innerHTML=`<section role="dialog" aria-modal="true" class="lb-dialog-card">${html}</section>`;bind?.();d.onkeydown=e=>{if(e.key==='Tab'){const all=[...d.querySelectorAll('button,select,input,a[href]')].filter(n=>!n.disabled),at=all.indexOf(document.activeElement),next=(at+(e.shiftKey?-1:1)+all.length)%all.length;e.preventDefault();all[next]?.focus();}};d.querySelector('button,select')?.focus();}
 function showControllerGuide(){const was=paused;if(page==='play')pause(true,'Controller guide opened');dialog(controllerGuide(),()=>$('#lbGuideClose').onclick=()=>{closeDialog();if(page==='play')pause(was);});}
 function closeDialog(){$('#lbDialog').hidden=true;$('#lbDialog').innerHTML='';}
 function showSettings(){const caps=graphics.caps,s=graphics.settings;dialog(`<p class="lb-eyebrow">GRAPHICS & PERFORMANCE</p><h2>Make this world yours.</h2><p>${caps.renderer}. ${caps.gpu?'Effects are limited to reported capabilities.':'Compatibility mode uses reduced geometry/distance and texture sampling. GPU effects are unavailable.'}</p><div class="lb-fields"><label>Preset<select id="lbLivePreset">${presets()}</select></label><label>Resolution scale<select id="lbScale">${[.5,.7,.9,1,1.15,1.25].map(v=>`<option ${v===s.resolutionScale?'selected':''}>${v}</option>`).join('')}</select></label><label>Surface textures<select id="lbTexture"><option value="low" ${s.texture==='low'?'selected':''}>512 px</option><option value="high" ${s.texture==='high'?'selected':''}>1024 px</option></select></label><label>View distance<input id="lbDistance" type="range" min="12" max="68" value="${s.distance}"></label><label>Foliage density<input id="lbFoliage" type="range" min=".2" max="1.7" step=".1" value="${s.foliage}"></label><label>Shadow map<select id="lbShadow" ${!caps.shadows?'disabled':''}>${[0,1024,2048,4096].map(v=>`<option ${v===s.shadowSize?'selected':''}>${v}</option>`).join('')}</select></label><label>Particle density<input id="lbParticles" type="range" min="0" max="220" value="${s.particles}"></label><label>Post-process MSAA<select id="lbMSAA" ${!caps.post?'disabled':''}>${[1,2,4].map(v=>`<option ${v===s.samples?'selected':''} ${v>caps.maxSamples?'disabled':''}>${v}</option>`).join('')}</select></label><label>Physics objects<input id="lbPhysics" type="range" min="0" max="48" value="${s.physics}"></label><label>Lighting / weather<select id="lbWeather"><option value="day">Day</option><option value="dusk">Dusk</option><option value="night">Night</option><option value="rain">Rain</option></select></label><label>Target FPS<select id="lbTarget"><option ${target===30?'selected':''}>30</option><option ${target===60?'selected':''}>60</option></select></label></div><div class="lb-checks">${[['ao','Ambient occlusion'],['reflections','Water reflections'],['post','Bloom / FXAA post-processing']].map(([key,label])=>`<label><input type="checkbox" data-effect="${key}" ${s[key]?'checked':''} ${!caps[key]?'disabled':''}>${label} ${!caps[key]?'· N/A':''}</label>`).join('')}</div><p class="lb-note">Imported model textures are fixed up to 1024 px. Surface quality changes terrain/bark maps. Formal runs hold all settings fixed. System RAM and VRAM readings are unavailable.</p><button id="lbApply" class="lb-primary">APPLY & RETURN</button><button id="lbTune">FIND MY BEST SETTINGS</button><button id="lbStartBench">RUN 35-SECOND FOREST BASELINE</button><button id="lbSettingsClose">CANCEL</button>`,()=>{$('#lbApply').onclick=()=>{preset=$('#lbLivePreset').value;const over={resolutionScale:+$('#lbScale').value,texture:$('#lbTexture').value,distance:+$('#lbDistance').value,foliage:+$('#lbFoliage').value,physics:+$('#lbPhysics').value,particles:+$('#lbParticles').value,shadowSize:+$('#lbShadow').value,samples:+$('#lbMSAA').value};host.querySelectorAll('[data-effect]').forEach(e=>over[e.dataset.effect]=e.checked);const weather=$('#lbWeather').value;applySettings(over);view.setWeather(weather);closeDialog();pause(false);};$('#lbLivePreset').onchange=e=>{const draft=resolveGraphics(e.target.value,caps);for(const [id,key]of [['lbScale','resolutionScale'],['lbTexture','texture'],['lbDistance','distance'],['lbFoliage','foliage'],['lbShadow','shadowSize'],['lbParticles','particles'],['lbPhysics','physics'],['lbMSAA','samples']])$('#'+id).value=draft[key];host.querySelectorAll('[data-effect]').forEach(n=>n.checked=draft[n.dataset.effect]);};$('#lbTarget').onchange=e=>target=+e.target.value;$('#lbSettingsClose').onclick=()=>{closeDialog();pause(false);};$('#lbStartBench').onclick=()=>launch('baseline');$('#lbTune').onclick=()=>launch('tune');});}
 function showResult(r){dialog(`<p class="lb-eyebrow">MEASURED FOREST BASELINE · ${esc(r.metadata.renderer)}</p><h2>${fmt(r.overall.averageFPS)} <small>AVERAGE FPS</small></h2><div class="lb-result-grid"><span><b>${fmt(r.overall.onePercentLowFPS)}</b>1% LOW FPS</span><span><b>${fmt(r.overall.medianMs)} ms</b>MEDIAN FRAME</span><span><b>${fmt(r.overall.p95Ms)} ms</b>p95 FRAME</span><span><b>${fmt(r.overall.worstMs)} ms</b>WORST FRAME</span></div><p>${esc(r.settings.label)} · ${r.metadata.renderWidth}×${r.metadata.renderHeight} · ${r.overall.frames} frames<br>Babylon.js 9.32.0 / Havok 1.3.14 · ${r.settings.ao?'AO on':'AO off'} · ${r.settings.reflections?'planar reflections':'reflections off'}</p><table><thead><tr><th>Forest stage</th><th>AVG FPS</th><th>1% LOW</th><th>p95 ms</th></tr></thead><tbody>${r.stages.map(s=>`<tr><td>${esc(s.name)}</td><td>${fmt(s.averageFPS)}</td><td>${fmt(s.onePercentLowFPS)}</td><td>${fmt(s.p95Ms)}</td></tr>`).join('')}</tbody></table><p class="lb-note">${r.overall.sampleLimited?'Fewer than 100 frames were captured; 1% lows use a small sample. ':''}This is the forest traversal baseline; its edition is ${esc(r.metadata.baseline||'living-forest-v1')}. Compare runs from the same edition. It is not a combat stress test. Software results do not predict Windows GPU performance. No synthetic score, RAM estimate or VRAM estimate is shown.</p><button id="lbResultPlay" class="lb-primary">PLAY THE FOREST</button><button id="lbJSON">EXPORT JSON</button><button id="lbCSV">EXPORT CSV</button><button id="lbCompare">COMPARE RUNS</button><button id="lbRerun">RUN AGAIN</button>`,()=>{$('#lbResultPlay').onclick=()=>launch('adventure');$('#lbJSON').onclick=()=>download(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),'Project-Limit-Break-forest-'+r.id+'.json');$('#lbCSV').onclick=()=>download(new Blob([benchmarkCSV(r)],{type:'text/csv'}),'Project-Limit-Break-forest-'+r.id+'.csv');$('#lbCompare').onclick=showHistory;$('#lbRerun').onclick=()=>launch('baseline');});}
 function showHistory(){dialog(`<p class="lb-eyebrow">DEVICE-LOCAL HISTORY · ${history().length} / 20 RUNS</p><h2>Compare the evidence.</h2><p>Compare renderer, resolution and settings before drawing conclusions. These are forest baseline results, separate from adventure scores.</p>${history().length?`<table><thead><tr><th>Run</th><th>Renderer / preset</th><th>Resolution</th><th>AVG / 1% FPS</th></tr></thead><tbody>${history().slice().reverse().map((r,i)=>`<tr><td><button data-result="${esc(r.id)}">${new Date(r.at).toLocaleString()}</button></td><td>${esc(r.metadata.renderer)} / ${esc(r.settings.label)}</td><td>${r.metadata.renderWidth}×${r.metadata.renderHeight}</td><td>${fmt(r.overall.averageFPS)} / ${fmt(r.overall.onePercentLowFPS)}</td></tr>`).join('')}</tbody></table>`:'<p>No measurements yet. Run the automatic Forest Baseline to record actual frames.</p>'}<button id="lbHistoryClose" class="lb-primary">CLOSE</button>`,()=>{host.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showResult(history().find(r=>r.id===b.dataset.result)));$('#lbHistoryClose').onclick=()=>closeDialog();});}
 function padContext(){const background=document.hidden||document.hasFocus?.()===false,native=document.querySelector?.('dialog[open]'),custom=$('#lbDialog')&&!$('#lbDialog').hidden?$('#lbDialog'):null,loading=page==='play'&&$('#lbLoading')&&!$('#lbLoading').hidden,error=loading&&!!$('#lbRetry');return{key:page+':'+(background?'background':native?'instructions':custom?'dialog':error?'error':loading?'loading':paused?'pause':run?'baseline':'play'),mode:background?'background':native||custom||error||page!=='play'||paused?'menu':loading?'loading':run?'baseline':'game',surface:native||custom||host,canPause:!background&&page==='play'&&!!view&&!native&&!custom};}
 const padUI=createControllerUI({root:host,hub,getContext:padContext,onPause:()=>paused&&mode!=='adventure'?launch('adventure'):pause(!paused),onBack:()=>{const native=document.querySelector?.('dialog[open]');if(native){native.querySelector('[data-instructions-back]')?.click();return;}if(!$('#lbDialog')?.hidden){const close=$('#lbGuideClose')||$('#lbSettingsClose')||$('#lbHistoryClose');if(close)close.click();else closeDialog();return;}if(paused)mode==='adventure'?pause(false):launch('adventure');else if(page==='setup')leave();},onHelp:()=>gate.review(),onCenter:i=>{const p=model?.players[i];if(p&&runtime){runtime.camera.alpha=-Math.PI/2-p.angle;runtime.camera.beta=1.23;}},onLook:(i,x,y,dt)=>{if(runtime&&!paused&&!run&&i<model.players.length){runtime.camera.alpha-=x*dt*2.2;runtime.camera.beta=Math.max(.4,Math.min(1.3,runtime.camera.beta+y*dt*1.4));}},onStatus:text=>{const status=$('#lbPadStatus');if(status&&status.textContent!==text)status.textContent=text;}});
 const visibility=()=>{if(document.hidden&&runtime)pause(true,'Tab hidden');};document.addEventListener('visibilitychange',visibility);const resize=()=>{if(run){pause(true,'Viewport resized');if($('#lbBenchStatus'))$('#lbBenchStatus').textContent='Benchmark stopped after resize. Run again at a fixed resolution.';}};window.addEventListener('resize',resize);const blur=()=>{if(runtime)pause(true,'Window unfocused');};window.addEventListener('blur',blur);setup();if(initialPage==='records')showHistory();return()=>{disposed=true;padUI.dispose();disposeScene();gate.dispose();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('resize',resize);window.removeEventListener('blur',blur);};
}
